const s={ui:{fig:"Abb. 2",title:"Reißverschluss-Enden einfassen",svgLabel:"Eine isometrische Zeichnung, wie die Enden eines Reißverschlusses mit Abschlussstücken aus Stoff eingefasst werden: ein Streifen, etwas breiter als das Reißverschlussband, wie Schrägband gefaltet — zwei Kanten zur Mitte, dann zur Hälfte; über jedes Ende des Reißverschlusses geschoben und knapp an den eingeschlagenen Kanten abgesteppt, direkt hinter dem Stopper, nie darüber.",prev:"Vorheriger Schritt",dot:(e,n)=>e?`Schritt ${e}: ${n}`:n,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,n)=>`Schritt ${e} von ${n}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Stoffstücke abheben",putTogether:"Wieder anlegen",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT"},stitches:{straight:"Geradstich"},labels:{strip:"ein Stoffstreifen",widerThanTape:"etwas breiter als das Band",edgesMiddle:"Kanten zur Mitte",press:"bügeln",inHalf:"zur Hälfte falten",slipOn:"über das RV-Ende",pastStop:"direkt hinter dem Stopper",alongEdge:"knapp an den Kanten",notOverStop:"nicht über den Stopper",otherEnd:"das andere Ende genauso",thenLined:"dann wie die erste Variante"},steps:[{title:"Reißverschluss-Enden einfassen",text:"Beide Enden des Reißverschlusses sind mit kleinen Abschlussstücken aus Stoff eingefasst, direkt hinter den Stoppern abgesteppt. Tippe, um die Stoffstücke abzuheben."},{title:"Ein Stoffstreifen",text:"Schneide einen Stoffstreifen zu, etwas breiter als das Reißverschlussband — einen für jedes Ende des Reißverschlusses.",details:["Schneide einen kurzen Stoffstreifen zu, etwas breiter als das Reißverschlussband: Das Abschlussstück deckt das Ende des Reißverschlusses von Kante zu Kante ab.","Du brauchst zwei: eins für jedes Ende des Reißverschlusses.","Die Größe ist in jeder Anleitung anders; wichtig ist nur, dass der Streifen etwas breiter als das Reißverschlussband ist."]},{title:"Kanten zur Mitte",text:"Lege den Streifen mit der linken Seite nach oben, falte zwei gegenüberliegende Kanten zur Mitte und bügle sie, wie Schrägband.",details:["Lege den Streifen mit der linken Seite nach oben.","Schlage zwei gegenüberliegende Kanten so ein, dass sie sich in der Mitte treffen, links auf links.","Bügle die Falten."]},{title:"Zur Hälfte falten",text:"Falte den Streifen in der Mitte zur Hälfte, die eingeschlagenen Kanten innen, und bügle ihn. Das Abschlussstück ist fertig: auf der einen Seite die Faltkante, auf der anderen die eingeschlagenen Kanten.",details:["Falte den Streifen in der Mitte zur Hälfte, so dass die eingeschlagenen Kanten innen aufeinandertreffen.","Bügle: Das Abschlussstück hat jetzt auf der einen Seite die Faltkante und auf der anderen die beiden eingeschlagenen Kanten.","Das zweite Abschlussstück machst du genauso."]},{title:"Über das Ende",text:"Schiebe das Abschlussstück über das Ende des Reißverschlusses: Das Ende steckt innen bis zur Faltkante, die eingeschlagenen Kanten liegen direkt hinter dem Stopper.",details:["Öffne das Abschlussstück ein wenig und schiebe das Ende des Reißverschlusses hinein, bis zur Faltkante.","Die eingeschlagenen Kanten liegen direkt hinter dem Stopper, nicht darauf.","Auf beiden Seiten steht das Abschlussstück ein wenig über den Reißverschluss hinaus."]},{title:"Abschlussstück absteppen",text:"Steppe mit dem Reißverschlussfuß knapp an den eingeschlagenen Kanten ab, durch das Abschlussstück und das Reißverschlussband. Nähe nie über den Stopper oder die Zähne.",details:["Setze den Reißverschlussfuß ein: Mit ihm nähst du dicht an den eingeschlagenen Kanten.","Steppe quer über das Abschlussstück, knapp an den Kanten, durch alle Lagen und das Reißverschlussband.","Die Naht bleibt auf dem Band, hinter dem Stopper: Nähe nie über den Stopper oder die Zähne. Sie sind oft aus Metall, und die Nadel kann brechen."]},{title:"Das andere Ende",text:"Schiebe das zweite Abschlussstück über das andere Ende und steppe es genauso mit dem Reißverschlussfuß ab, hinter dem Stopper. Danach nähst du den Reißverschluss ein wie den Reißverschluss mit Futter.",details:["Schiebe das zweite Abschlussstück über das andere Ende des Reißverschlusses, die eingeschlagenen Kanten direkt hinter dem Stopper.","Steppe mit dem Reißverschlussfuß knapp an den Kanten ab, nicht über den Stopper.","Den Rest nähst du wie bei der ersten Variante, „Reißverschluss mit Futter“: Der Link steht unter dieser Zeichnung."]}],legend:[{title:"Abschlussstück",text:"Stoffstreifen, wie Schrägband gefaltet · etwas breiter als das Reißverschlussband"},{title:"Naht",text:"knapp an den eingeschlagenen Kanten, hinter dem Stopper"},{title:"Stopper",text:"nie darüber nähen"},{title:"Reißverschluss",text:"seine Enden stecken in den Abschlussstücken"}]};export{s as default};
